entries[91787] = { ["name"] = "Plattenhelm des bösartigen Gladiators", ["text"] = "Saison 13\nWird beim Aufheben gebunden\nKopf Platte\n4191 Rüstung\n+775 Stärke\n+1.625 Ausdauer\nErhöht Eure Waffenkundewertung um + 677.\nErhöht Eure Meisterschaftswertung um + 437.\nErhöht Eure PvP-Macht um + 536.\n\nMetasockel\nRoter Sockel\nSockelbonus: + 180 PvP-Macht\n\nHaltbarkeit 100 / 100\nKlassen: Krieger\nBenötigt Stufe 90\n\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenstulpen des Gladiators\nPlattenhelm des Gladiators\nPlattenbeinschützer des Gladiators\nPlattenschultern des Gladiators\n(2) Set : Entwaffnungsdauer um 50% verringert.\n(2) Set : Erhöht die PvP-Macht um 500.\n(4) Set : Erhöht Euer Bewegungstempo nach dem Einsatz von 'Heldenhafter Sprung' 3 Sek. lang um 70%.\n(4) Set : Erhöht die PvP-Macht um 1000.\nVerkaufspreis:" }
entries[91789] = { ["name"] = "Plattenbeinschützer des bösartigen Gladiators", ["text"] = "Saison 13\nWird beim Aufheben gebunden\nBeine Platte\n4514 Rüstung\n+855 Stärke\n+1.625 Ausdauer\nErhöht Eure kritische Trefferwertung um + 677.\nErhöht Eure Tempowertung um + 517.\nErhöht Eure PvP-Macht um + 536.\n\nRoter Sockel\nBlauer Sockel\nSockelbonus: + 120 PvP-Macht\n\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 90\n\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenstulpen des Gladiators\nPlattenhelm des Gladiators\nPlattenbeinschützer des Gladiators\nPlattenschultern des Gladiators\n(2) Set : Entwaffnungsdauer um 50% verringert.\n(2) Set : Erhöht die PvP-Macht um 500.\n(4) Set : Erhöht Euer Bewegungstempo nach dem Einsatz von 'Heldenhafter Sprung' 3 Sek. lang um 70%.\n(4) Set : Erhöht die PvP-Macht um 1000.\nVerkaufspreis:" }
entries[91791] = { ["name"] = "Plattenschultern des bösartigen Gladiators", ["text"] = "Saison 13\nWird beim Aufheben gebunden\nSchulter Platte\n3869 Rüstung\n+674 Stärke\n+1.208 Ausdauer\nErhöht Eure Tempowertung um + 503.\nErhöht Eure Waffenkundewertung um + 423.\nErhöht Eure PvP-Macht um + 398.\n\nGelber Sockel\nSockelbonus: + 60 Stärke\n\nHaltbarkeit 100 / 100\nKlassen: Krieger\nBenötigt Stufe 90\n\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenstulpen des Gladiators\nPlattenhelm des Gladiators\nPlattenbeinschützer des Gladiators\nPlattenschultern des Gladiators\n(2) Set : Entwaffnungsdauer um 50% verringert.\n(2) Set : Erhöht die PvP-Macht um 500.\n(4) Set : Erhöht Euer Bewegungstempo nach dem Einsatz von 'Heldenhafter Sprung' 3 Sek. lang um 70%.\n(4) Set : Erhöht die PvP-Macht um 1000.\nVerkaufspreis:" }
entries[91802] = { ["name"] = "Jadegrüne pandarische Drachenleine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Pandarendrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\nVerkaufspreis:" }
entries[91803] = { ["name"] = "Schnappwurzknolle", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 85\nBenutzen: Erhöht das Tempo 25 Sek. lang um 4000 . (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[91806] = { ["name"] = "Instabiler Portalsplitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: \"Pflanzt\" den instabilen Portalsplitter ein.\n\"Kristalle aus chaotischer Arkanenergie von stark frequentierten Portalen. Die Erde des Gehöfts Sonnensang stabilisiert diese Energie und erzeugt einen Splitter, der auf dem Gehöft zerbrochen werden kann, um ein Einwegportal zu einer Hauptstadt zu öffnen.\"\nVerkaufspreis:" }
entries[91807] = { ["name"] = "Kopf von Or", ["text"] = "Questgegenstand\n\"Die Überraschung ob seiner Niederlage steht immer noch in Ors Gesicht geschrieben – eines seiner Gesichter zumindest.\"" }
entries[91808] = { ["name"] = "Kopf von Dac", ["text"] = "Questgegenstand\n\"Selbst im Tod streckt Euch Dac noch seine Zunge entgegen.\"" }
entries[91809] = { ["name"] = "Kopf von Ruk'ra", ["text"] = "Questgegenstand\n\"Ein Ausdruck typischen Kor'kronstolzes und -trotzes lässt sich noch immer in dieser Grimasse erkennen.\"" }
entries[91810] = { ["name"] = "Kopf von Klitzefritz", ["text"] = "Questgegenstand\n\"Hat immer noch die Gasmaske auf.\"" }
entries[91814] = { ["name"] = "Makellose goldene Kronenfeder", ["text"] = "Questgegenstand\n\"Eine absolut saubere, frische Feder eines Kindes von Chi-Ji.\"" }
entries[91815] = { ["name"] = "Makellose schwarze Kronenfeder", ["text"] = "Questgegenstand\n\"Eine pechschwarze Feder eines großen Kranichs.\"" }
entries[91816] = { ["name"] = "Unbeschädigte Yakkeule", ["text"] = "Questgegenstand\n\"Fettes Yakfleisch. Der Traum eines jeden Tigergaumens.\"" }
entries[91817] = { ["name"] = "Müffelnder verrotteter Fisch", ["text"] = "Questgegenstand\n\"Der Geruch ist... überwältigend.\"" }
entries[91819] = { ["name"] = "Robuste Kranichschlinge", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: [Sturdy Trap] (1)\nDieser Gegenstand startet eine Quest.\n\"Eine fachmännisch geknotete Schlinge, der selbst ein kräftiges Kranichbein nicht entkommen kann.\"" }
entries[91821] = { ["name"] = "Robuste Tigerfalle", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: [Sturdy Trap] (1)\nDieser Gegenstand startet eine Quest.\n\"Eine stramm gezurrte Falle, mit der extragroße Tiger gefangen und bewegungsunfähig gemacht werden können.\"" }
entries[91822] = { ["name"] = "Robuster Krabbenkorb", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: [Sturdy Trap] (1)\nDieser Gegenstand startet eine Quest.\n\"Ein widerstandsfähiger Korb, mit dem extragroße Krabben gefangen werden können.\"" }
entries[91823] = { ["name"] = "Belebbarer Stein", ["text"] = "Questgegenstand\n\"Dieser Stein scheint zu vibrieren, wenn Ihr ihn berührt.\"" }
entries[91834] = { ["name"] = "Uralter Blutkronenkranich", ["text"] = "Questgegenstand\n\"Der betäubte Körper eines großen, kräftigen Kranichs.\"" }
entries[91835] = { ["name"] = "Alter Krasaritiger", ["text"] = "Questgegenstand\n\"Der betäubte Körper eines großen, kräftigen Tigers.\"" }
entries[91836] = { ["name"] = "Kolossale Zwingzange", ["text"] = "Questgegenstand\n\"Der betäubte Körper einer großen, kräftigen Krabbe.\"" }
entries[91838] = { ["name"] = "Schlachtbefehl der Löwenlandung", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Schlachtbefehl war für Mitglieder der Allianz bestimmt, die in der Löwenlandung ihren Dienst leisten. Bringt sie zu Ongrom Schwarzzahn bei der Herrschaftsfeste.\"" }
entries[91846] = { ["name"] = "Fass mit \"destilliertem\" Treibstoff", ["text"] = "Questgegenstand\n\"Eine Mischung aus übelriechendem Meerwasser und Treibstoff schwappt in diesem Fass herum.\"" }
entries[91847] = { ["name"] = "Bauholz der Herrschaftsfeste", ["text"] = "Questgegenstand\n\"Flexibel und bereit zum Verbauen.\"" }
entries[91848] = { ["name"] = "Aufgeladener Eisenerzbrocken", ["text"] = "Questgegenstand\n\"Das Erz pulsiert vor dunkler Energie. Das kann nichts Gutes bedeuten...\"" }
entries[91850] = { ["name"] = "Portalsplitter: Orgrimmar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Orgrimmar.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
