entries[91869] = { ["name"] = "Verdorbenes Zwingzangenfleisch", ["text"] = "Questgegenstand\n\"Ein ranziger Gestank geht von diesem eitrigen Fleisch aus.\"" }
entries[91871] = { ["name"] = "Gezackter Stein", ["text"] = "Questgegenstand\n\"Der Stein hat eine rauhe, aber warme Oberfläche.\"" }
entries[91874] = { ["name"] = "Brocken eigenartiges Fleisch", ["text"] = "Questgegenstand\n\"Ein fürchterlich riechender Schleim trieft von dem Fleisch. Es wird Tage dauern, bis Ihr den Gestank aus Euren Taschen bekommt.\"" }
entries[91875] = { ["name"] = "Kreissäges Hausmarke", ["text"] = "Questgegenstand\nEinzigartig\n\"Bixis geheimes Familienrezept für Treibstoff, das von einer Generation Kreissägen zur nächsten weitergegeben wurde.\"" }
entries[91877] = { ["name"] = "Schlachtbefehl der Herrschaftsfeste", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Schriftstück, das in der Sprache der Orcs verfasst ist und eine Karte von Pandaria zeigt, auf der mit roter Tinte Punkte markiert sind. Bringt es zu Administrator Grantley in der Löwenlandung.\"" }
entries[91902] = { ["name"] = "Universalfernsteuerung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Sendet auf Frequenz Drei Zwo Neun. (5 Sek. Abklingzeit)\n\"Nicht direkt in die Lichtquelle blicken. Hersteller übernimmt keine Haftbarkeit.\"" }
entries[91904] = { ["name"] = "Stapelbarer Hirsch", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen stapelbaren Hirsch am Zielort. Wenn sich ein anderer stapelbarer Hirsch in der Nähe befindet, wird sich Euer stapelbarer Hirsch auf den anderen stapelbaren Hirsch stapeln. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[91906] = { ["name"] = "Brüchige Wurzel", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Stellt allen Arbeitern Materialien zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 30% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[91907] = { ["name"] = "Bauholz der Löwenlandung", ["text"] = "Questgegenstand\n\"Dieses Holz wurde kürzlich in den Wäldern um die Löwenlandung geschlagen – und noch kürzlicher von feigen Arbeitern zurückgelassen.\"" }
entries[91971] = { ["name"] = "Kampfrationen", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
