entries[91982] = { ["name"] = "Weapon - Bow_2h_Crossbow_PVPPandariaS2_C_01 - Green", ["text"] = "Distanz Armbrust\n2 - 4 Schaden Tempo 2.00\n(1.50 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
