entries[92016] = { ["name"] = "Hochwertige Verbrenninatorformel für Versorgungsgüter", ["text"] = "Questgegenstand\nBenutzen: Zerstört diese Vorräte!" }
entries[92019] = { ["name"] = "Der Bilgewässer Molotow", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Flasche brennenden, umfunktionierten Fusels nach einem Gyrokopter X2 der Himmelsfeuer.\n\"Ein starkes Gemisch aus hochreaktiven, brennbaren Chemikalien, serviert mit einem brennenden Taschentuch.\"" }
entries[92026] = { ["name"] = "Weapon - Shield_PVPPandariaS2_C_02", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n28 Rüstung\n1 Blocken\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[92027] = { ["name"] = "Weapon - Shield_PVPPandariaS2_C_02 - Horde", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n28 Rüstung\n1 Blocken\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[92028] = { ["name"] = "Weapon - Shield_PVPPandariaS2_C_02 - Alliance", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n28 Rüstung\n1 Blocken\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[92029] = { ["name"] = "Weapon - Shield_PVPPandariaS2_C_02 - Purple", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n28 Rüstung\n1 Blocken\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[92035] = { ["name"] = "Verziertes Zepter", ["text"] = "Ein wenig Geduld\nEinzigartig\n\"Ein uraltes Moguartefakt.\"" }
entries[92036] = { ["name"] = "Stab des Affenkönigs", ["text"] = "Questgegenstand\n\"Ihr verspürt große Macht in diesem einfach anmutenden Stab. So sehr Ihr es auch versucht, er lässt sich nicht benutzen.\"\nVerkaufspreis:" }
entries[92049] = { ["name"] = "Söldnervertrag: Magier", ["text"] = "Benutzen: Heuert einen Magier an, der Hordespielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n30 m Reichweite\nSofort\nRequires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92050] = { ["name"] = "Söldnervertrag: Paladin", ["text"] = "Benutzen: Heuert einen Paladin an, der Hordespielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht\n30 m Reichweite\nSofort\nRequires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 3000 erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92051] = { ["name"] = "Söldnervertrag: Priester", ["text"] = "Benutzen: Heuert einen Priester an, der Hordespielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 m Reichweite Spontan\nRequires Priest\nRequires level 22 Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92052] = { ["name"] = "Söldnervertrag: Druide", ["text"] = "Benutzen: Heuert einen Druiden an, der Hordespielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n30 m Reichweite\nSofort\nRequires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92053] = { ["name"] = "Söldnervertrag: Krieger", ["text"] = "Benutzen: Heuert einen Krieger an, der Hordespielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n30 m Reichweite\nSofort\nRequires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis." }
entries[92054] = { ["name"] = "Söldnervertrag: Schurke", ["text"] = "Benutzen: Heuert einen Schurken an, der Hordespielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n30 m Reichweite\nSofort\nRequires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis." }
entries[92055] = { ["name"] = "Söldnervertrag: Schamane", ["text"] = "Benutzen: Heuert einen Schamanen an, der Hordespielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n30 m Reichweite\nSofort\nRequires Shaman\nRequires level 55 Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis." }
entries[92056] = { ["name"] = "Portaltreibstoff: Außenposten Zündmine", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Zweiwegportal zum Außenposten Zündmine aufrechtzuerhalten." }
entries[92057] = { ["name"] = "Portaltreibstoff: Orgrimmar", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Einwegportal nach Orgrimmar aufrechtzuerhalten." }
entries[92058] = { ["name"] = "Portaltreibstoff: Schrein der Zwei Monde", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Einwegportal zum Schrein der Zwei Monde aufrechtzuerhalten." }
entries[92059] = { ["name"] = "Bankett der Herrschaftsfeste", ["text"] = "Benutzen: Platziert ein Bankett für Hordecharaktere in der Herrschaftsfeste. Hält 20 Min. lang an." }
