entries[92417] = { ["name"] = "Ausgrabungsbotfernsteuerung", ["text"] = "Questgegenstand\nBenutzen: Ruft einen Ausgrabungsbot herbei, der an Eurer Seite kämpft. Funktioniert nur in der Krasarangwildnis. (1 Min Abklingzeit)\n\"Mit diesem Gerät solltet ihr die Ausgrabungsbots im Steinbruch der Löwenlandung kontrollieren können. Die Betonung liegt hierbei auf \"solltet\"...\"" }
entries[92421] = { ["name"] = "Bewachungsvertrag: Friedhof", ["text"] = "Benutzen: Heuert Wachen an, die einen eroberbaren Friedhof in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Friedhofs befinden und Eure Fraktion muss ihn kontrollieren." }
entries[92422] = { ["name"] = "Bewachungsvertrag: Turm", ["text"] = "Benutzen: Heuert Wachen an, die einen eroberbaren Turm in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Turms befinden und Eure Fraktion muss ihn kontrollieren." }
entries[92425] = { ["name"] = "Uralte Tafel der Korun", ["text"] = "Questgegenstand\n\"Diese Steintafel ist mit machtvollen Mogusymbolen übersät.\"\n<Zum Lesen rechtsklicken>" }
entries[92426] = { ["name"] = "Versiegelter Foliant der verlorenen Legion", ["text"] = "Einzigartig\nBenötigt Stufe 90\nBenutzen: Mit einem Gesundheitsstein verbinden, um den Folianten an Euch zu binden.\n\"Abgesehen von der Kette und dem Schloss, die es binden, sieht das Buch ungewöhnlich normal aus.\"" }
entries[92427] = { ["name"] = "Bewachungsvertrag: Turm", ["text"] = "Benutzen: Heuert Wachen an, die einen eroberbaren Turm in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Turms befinden und Eure Fraktion muss ihn kontrollieren." }
entries[92428] = { ["name"] = "Bewachungsvertrag: Friedhof", ["text"] = "Benutzen: Heuert Wachen an, die einen eroberbaren Friedhof in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Friedhofs befinden und Eure Fraktion muss ihn kontrollieren." }
entries[92429] = { ["name"] = "Bankett der Löwenlandung", ["text"] = "Benutzen: Platziert ein Bankett für Allianzcharaktere in der Löwenlandung. Hält 20 Min. lang an." }
entries[92430] = { ["name"] = "Portalreagenzien: Schrein der Sieben Sterne", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Einwegportal zum Schrein der Sieben Sterne aufrechtzuerhalten." }
entries[92431] = { ["name"] = "Portalreagenzien: Sturmwind", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Einwegportal nach Sturmwind aufrechtzuerhalten." }
entries[92432] = { ["name"] = "Portalreagenzien: Himmelsfeuer", ["text"] = "Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Zweiwegportal zur Himmelsfeuer aufrechtzuerhalten." }
entries[92433] = { ["name"] = "Söldnervertrag: Schamane", ["text"] = "Benutzen: Heuert einen Schamanen an, der Allianzspielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n30 m Reichweite\nSofort\nRequires Shaman\nRequires level 55 Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis." }
entries[92434] = { ["name"] = "Söldnervertrag: Schurke", ["text"] = "Benutzen: Heuert einen Schurken an, der Allianzspielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n30 m Reichweite\nSofort\nRequires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis." }
entries[92435] = { ["name"] = "Söldnervertrag: Krieger", ["text"] = "Benutzen: Heuert einen Krieger an, der Allianzspielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n30 m Reichweite\nSofort\nRequires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis." }
entries[92436] = { ["name"] = "Söldnervertrag: Druide", ["text"] = "Benutzen: Heuert einen Druiden an, der Allianzspielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n30 m Reichweite\nSofort\nRequires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92437] = { ["name"] = "Söldnervertrag: Priester", ["text"] = "Benutzen: Heuert einen Priester an, der Allianzspielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 m Reichweite Spontan\nRequires Priest\nRequires level 22 Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92438] = { ["name"] = "Söldnervertrag: Paladin", ["text"] = "Benutzen: Heuert einen Paladin an, der Allianzspielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht\n30 m Reichweite\nSofort\nRequires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 3000 erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92439] = { ["name"] = "Söldnervertrag: Magier", ["text"] = "Benutzen: Heuert einen Magier an, der Allianzspielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n30 m Reichweite\nSofort\nRequires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92440] = { ["name"] = "Faksimile der Archäologischen Akademie", ["text"] = "\"Eine Abschrift der uralten Tafel der Korun. Darin wird der Ursprung der Götterglocke beschrieben.\"\n<Zum Lesen rechtsklicken>" }
entries[92441] = { ["name"] = "Kodex von Xerrath", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 90\n\"Als Ihr das Buch aufhebt, erklingen schreckliche, geflüsterte Mysterien in Euren Ohren, die Euren Verstand peinigen…\"" }
entries[92442] = { ["name"] = "Banner der Horde", ["text"] = "Einzigartig (20)\nBenutzen: Stellt ein Banner der Horde auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\nIhr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Allianz können versuchen, Eure Banner niederzubrennen." }
entries[92443] = { ["name"] = "Banner der Allianz", ["text"] = "Einzigartig (20)\nBenutzen: Stellt ein Banner der Allianz auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\nIhr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Horde können versuchen, Eure Banner niederzubrennen." }
entries[92444] = { ["name"] = "Fleischige Keule", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[92470] = { ["name"] = "Schlangenöl", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Stellt allen Gnomenarbeitern Schlangenöl zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 50% des Grundwerts erhöht. Bis zu 3-mal stapelbar. 1 Sek. Abklingzeit." }
entries[92471] = { ["name"] = "Jubekas Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieses lädierte, in Leder gebundene Notizbuch hat schon bessere Zeiten gesehen.\"\n<Zum Lesen rechtsklicken>" }
entries[92472] = { ["name"] = "Durchweichtes Tagebuch", ["text"] = "Ein wenig Geduld\nEinzigartig\n\"Die Wahrscheinlichkeit, dies hier zu finden, kann nicht mehr als eins zu einer Million sein.\"" }
entries[92474] = { ["name"] = "Besonders schmalzige Allianzohren", ["text"] = "Questgegenstand\n\"Zündmines patentierte Glücksohren. Nur echt mit dem Schmalzpfropfen!\"" }
entries[92475] = { ["name"] = "\"Neue\" und \"verbesserte\" Infrarot-Hitzebrille", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Neue und verbesserte Infrarottechnologie! Entdeckt Infiltrierer bevor sie Euch entdecken!\n\"Von \"neu\" und \"verbessert\" ist hier wenig zu erkennen.\"" }
entries[92484] = { ["name"] = "Versiegeltes Schreiben", ["text"] = "Questgegenstand\n\"Sieht unglaublich unspektakulär aus.\"" }
entries[92493] = { ["name"] = "Bilgewässer Sprengkapsel", ["text"] = "Questgegenstand\n\"Großartig zum Sprengen!\"" }
